		col += uSunColor * pow(max(dot(r, uSunDir), 0.0), 600.0) * 6.0 * (1.0 - uNight) + uSunColor * pow(max(dot(r, uSunDir), 0.0), 40.0) * 0.12 * (1.0 - uNight);
